using System;using System.IO;using System.Text;using System.Linq;using System.Diagnostics;using System.Threading;using System.Windows;using System.Windows.Media.Media3D;
namespace GearLab {
 static class ViewerTests {
  static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
  static Result Build(int kind){var p=Engine.Starter(kind);if(kind==3){p.Ratio=60;p.Overall=222.82;Engine.FitOverall(p);}var r=Engine.Calculate(p);r.Model=CadBuilder.Build(r);Check(r.Valid&&r.Model.Valid,"valid kind "+kind);return r;}
  static double Area(SceneMesh m){double a=0;for(int j=0;j<m.Indices.Length;j+=3)a+=Vector3D.CrossProduct(m.Points[m.Indices[j+1]]-m.Points[m.Indices[j]],m.Points[m.Indices[j+2]]-m.Points[m.Indices[j]]).Length/2;return a;}
  static void DepthTest(string folder){var tube=new CadPart("front","front tube","fixed",System.Drawing.Color.Blue);tube.Sections.Add(new CadSection(10,20,CadLoop.Round(0,0,10),new[]{CadLoop.Round(0,0,5)}));var back=new CadPart("back","back plate","fixed",System.Drawing.Color.Red);back.Sections.Add(new CadSection(0,5,CadLoop.Round(0,0,10),null));foreach(bool reverse in new[]{false,true})using(var scene=new WpfScene()){var model=new CadAssembly();model.Parts.AddRange(reverse?new[]{back,tube}:new[]{tube,back});scene.Root.Measure(new Size(256,256));scene.Root.Arrange(new Rect(0,0,256,256));scene.SetResult(new Result{P=new Parameters(),Model=model},false);scene.Camera.Preset("Сверху");scene.Fit();string file=Path.Combine(folder,"depth-"+reverse+".png");scene.SavePng(file,256,256);int x=(int)(128+7*256/scene.Camera.Width);using(var bitmap=new System.Drawing.Bitmap(file)){var bore=bitmap.GetPixel(128,128);var front=bitmap.GetPixel(x,128);Check(bore.R>bore.B*2&&front.B>front.R*2,"pixel depth and visible bore, order="+reverse);}
    string picked=null;scene.Picked+=id=>picked=id;scene.Pick(new Point(128,128));Check(picked=="back","ray pick through bore");scene.Pick(new Point(x,128));Check(picked=="front","ray pick nearest solid");scene.ConfigureSection(2,15,false);scene.SavePng(Path.Combine(folder,"depth-cut-"+reverse+".png"),256,256);
   }}
  public static int Run(string folder){Directory.CreateDirectory(folder);var log=new StringBuilder();try{
   var tube=new CadPart("tube","test","shaft",System.Drawing.Color.SteelBlue);tube.Sections.Add(new CadSection(0,10,CadLoop.Round(0,0,10),new[]{CadLoop.Round(0,0,5)}));var mesh=SceneMesher.Build(tube,CancellationToken.None);double exact=Math.PI*750;Check(Math.Abs(mesh.SignedVolume()/exact-1)<.013,"tube winding/holes volume");
   foreach(int axis in new[]{0,1,2})foreach(bool positive in new[]{false,true}){var cut=MeshSection.Clip(mesh,Matrix3D.Identity,axis,axis==2?5:0,positive,1e-6);Check(Math.Abs((cut.Body.SignedVolume()+cut.Cap.SignedVolume())/exact-.5)<.01,"closed half-tube volume "+axis+" "+positive);Check(Math.Abs(Area(cut.Cap)/(axis==2?Math.PI*75:100)-1)<.015,"section cap area / open bore "+axis);}
   log.AppendLine("PASS watertight mesh: normals/winding; six half-tube cuts; cap area excludes bore; volume +/-1.3% circular preview tolerance.");
   DepthTest(folder);log.AppendLine("PASS rendered depth: rear plate visible through front bore; front ring occludes rear plate in both insertion orders; picking follows the same surfaces.");var camera=new OrbitCamera();camera.Fit(new Rect3D(-10,-10,-10,20,20,20),1.5);var anchor=camera.ScreenPoint(180,240,900,600);camera.Zoom(120,180,240,900,600);Check((camera.ScreenPoint(180,240,900,600)-anchor).Length<1e-8,"cursor anchored zoom");var target=camera.Target;camera.Pan(100,0,900);Check((camera.Target-target).Length>1,"pan changes target");camera.Orbit(10,20);Check(!double.IsNaN(camera.Camera.UpDirection.X),"camera pole stable");camera.Preset("Сверху");Check(Math.Abs(camera.Direction.Z-1)<1e-9&&!double.IsNaN(camera.Camera.UpDirection.X),"true top view stable");
   for(int kind=0;kind<4;kind++){var r=Build(kind);using(var scene=new WpfScene()){scene.Root.Measure(new Size(1000,800));scene.Root.Arrange(new Rect(0,0,1000,800));scene.SetResult(r,false);Check(scene.Ready&&scene.Nodes.Count==r.Model.Parts.Count,"ready scene "+kind);foreach(var node in scene.Nodes){double ratio=node.Source.SignedVolume()/node.Part.Volume();Check(ratio>.975&&ratio<1.025,"part volume "+node.Part.Id+" ratio="+ratio);Check(node.Frozen.IsFrozen,"frozen GPU geometry");}
     int builds=SceneMesher.Builds;var yaw=scene.Camera.Yaw;var position=scene.Camera.Target;var width=scene.Camera.Width;var original=scene.Nodes.Select(n=>n.Frozen).ToArray();var watch=Stopwatch.StartNew();for(int j=0;j<1000;j++)scene.UpdatePose(j*.017);watch.Stop();double poseMs=watch.Elapsed.TotalMilliseconds/1000;Check(SceneMesher.Builds==builds,"animation does not rebuild mesh");Check(scene.Nodes.Select((n,i)=>ReferenceEquals(n.Frozen,original[i])).All(x=>x),"geometry stable");Check(scene.Camera.Target==position&&scene.Camera.Width==width&&scene.Camera.Yaw==yaw,"animation preserves camera");
     var moving=scene.Nodes.First(n=>n.Motion.Moving);Check(moving.Motion.At(0,0)!=moving.Motion.At(.7,0),"motion bound "+kind);scene.UpdatePose(0);scene.SavePng(Path.Combine(folder,"kind-"+kind+"-full.png"),1000,800);foreach(var n in scene.Nodes)if(n.Part.Role=="housing"||n.Part.Reference||n.Part.Role=="fastener")scene.Hidden.Add(n.Part.Id);scene.RefreshVisibility();scene.UpdatePose(Math.PI/2);scene.SavePng(Path.Combine(folder,"kind-"+kind+"-motion.png"),1000,800);Check(SceneMesher.Builds==builds,"visibility reuses geometry");
     scene.Hidden.Clear();scene.RefreshVisibility();var b=scene.Bounds(false);scene.ConfigureSection(2,b.Z+b.SizeZ*.72,false);scene.SavePng(Path.Combine(folder,"kind-"+kind+"-section-z.png"),1000,800);watch.Restart();for(int j=0;j<100;j++)scene.UpdatePose(j*.02);watch.Stop();double localMs=watch.Elapsed.TotalMilliseconds/100;scene.ConfigureSection(0,.37,false);scene.SavePng(Path.Combine(folder,"kind-"+kind+"-section-x.png"),1000,800);watch.Restart();for(int j=0;j<3;j++)scene.UpdatePose(j*.02+.123);watch.Stop();double crossMs=watch.Elapsed.TotalMilliseconds/3;scene.ConfigureSection(-1,0,false);scene.SetExploded(true);scene.SavePng(Path.Combine(folder,"kind-"+kind+"-exploded.png"),1000,800);
     log.AppendLine("Kind "+kind+": "+scene.Nodes.Count+" bodies, "+scene.TriangleCount+" triangles; initial mesh "+scene.BuildMilliseconds.ToString("F1")+" ms; pose "+poseMs.ToString("F4")+" ms/frame (CPU updates only); cached Z cut "+localMs.ToString("F3")+" ms/frame; crossing X cut "+crossMs.ToString("F1")+" ms/frame.");
    }}
   using(var form=new MainForm(new TestDialogs()))form.ViewerUiRegression(folder,log);
   log.AppendLine("PASS camera anchor/pan/orbit; frozen meshes; motion all four transmissions; hidden components; three cut planes; screenshots; model unaffected by view.");File.WriteAllText(Path.Combine(folder,"viewer-results.txt"),log.ToString(),Encoding.UTF8);return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"viewer-error.txt"),log+Environment.NewLine+ex,Encoding.UTF8);return 1;}}
 }
 public partial class MainForm {
  internal void ViewerUiRegression(string folder,StringBuilder log){Opacity=0;ShowInTaskbar=false;Show();animation.Stop();Apply(Engine.Starter(0),true);ShowFullModel();System.Windows.Forms.Application.DoEvents();canvas.Viewer.SetResult(result,false); // same pending async task is completed by the message loop below
   var wait=Stopwatch.StartNew();while(!canvas.Viewer.Scene.Ready&&wait.Elapsed.TotalSeconds<30){System.Windows.Forms.Application.DoEvents();Thread.Sleep(10);}if(!canvas.Viewer.Scene.Ready)throw new Exception("Async UI scene failed: "+canvas.Viewer.Scene.Error);
   run.PerformClick();if(!canvas.ShowMotion)throw new Exception("3D run button");run.PerformClick();if(canvas.ShowMotion)throw new Exception("3D pause button");var model=result.Model;numbers["InputRpm"].Commit(45);calculate.PerformClick();if(!ReferenceEquals(result.Model,model))throw new Exception("RPM rebuilt CAD model");exportScope.SelectedIndex=1;if(!ReferenceEquals(result.Model,model))throw new Exception("Export scope rebuilt CAD model");hideHousing.Checked=true;if(!canvas.HideHousing)throw new Exception("Hide housing UI");hideHousing.Checked=false;canvas.Viewer.Scene.Camera.Zoom(120,200,200,900,600);fit.PerformClick();if(!canvas.Viewer.Scene.Ready)throw new Exception("fit UI");closingApproved=true;Close();log.AppendLine("PASS native UI: async worker attachment; run/pause in 3D; RPM/scope reuse CAD; housing toggle; fit button.");
  }
 }
}
